const NS='http://www.w3.org/2000/svg';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function svgNode(tag,attrs={},content=''){const n=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(content)n.textContent=content;return n;}
function rect(x,y,w,h,fill,rx=0,stroke='none',extra={}){return svgNode('rect',{x,y,width:w,height:h,fill,rx,stroke,...extra});}
function text(x,y,value,fill='#6d7e60',size=14,extra={}){return svgNode('text',{x,y,fill,'font-size':size,'text-anchor':'middle',direction:'rtl',...extra},value);}
function point(svg,e){const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());}
function listen(el,event,fn,signal){el.addEventListener(event,fn,{signal});}
function frame(container,title){container.innerHTML=`<div class="basic-wrap"><svg class="basic-scene" viewBox="0 0 900 480" role="group" aria-label="${title}"></svg><details class="basic-alternatives"><summary>بدائل النقر ولوحة المفاتيح</summary><div class="basic-controls"></div></details></div>`;return {svg:container.querySelector('svg'),controls:container.querySelector('.basic-controls')};}
