function drag(svg,handlers,signal){let active=null;
 const finish=(e,cancel=false)=>{if(!active||(e.pointerId!==undefined&&e.pointerId!==active.id))return;const a=active;active=null;document.body.classList.remove('dragging');if(svg.hasPointerCapture(a.id))svg.releasePointerCapture(a.id);if(cancel)handlers.cancel?.(a.data);else handlers.end?.(point(svg,e),a.data,e);};
 listen(svg,'pointerdown',e=>{if(e.button!==0||active)return;const p=point(svg,e);const data=handlers.start(p,e);if(data===false||data==null)return;e.preventDefault();active={id:e.pointerId,data};svg.setPointerCapture(e.pointerId);document.body.classList.add('dragging');},signal);
 listen(svg,'pointermove',e=>{if(!active||active.id!==e.pointerId)return;handlers.move(point(svg,e),active.data,e);},signal);
 listen(svg,'pointerup',e=>finish(e),signal);listen(svg,'pointercancel',e=>finish(e,true),signal);listen(svg,'lostpointercapture',e=>{if(active)finish(e,true);},signal);listen(window,'blur',()=>{if(active)finish({pointerId:active.id},true);},signal);
 listen(window,'keydown',e=>{if(e.key==='Escape'&&active){e.preventDefault();finish({pointerId:active.id},true);}},signal);
 signal.addEventListener('abort',()=>{if(active){if(svg.hasPointerCapture(active.id))svg.releasePointerCapture(active.id);active=null;}document.body.classList.remove('dragging');},{once:true});
}
function arrowControls(controls,callback,signal,label){controls.innerHTML=`<span>${label}</span><button type="button" data-dx="0" data-dy="-20" aria-label="إلى الأعلى">↑</button><button type="button" data-dx="20" data-dy="0" aria-label="إلى اليمين">→</button><button type="button" data-dx="0" data-dy="20" aria-label="إلى الأسفل">↓</button><button type="button" data-dx="-20" data-dy="0" aria-label="إلى اليسار">←</button><span class="basic-hint">أو ركّز العنصر واستخدم الأسهم. Escape يلغي السحب.</span>`;controls.querySelectorAll('button').forEach(b=>listen(b,'click',()=>callback(+b.dataset.dx,+b.dataset.dy),signal));}

